import{_ as n,o as r,c as t,ag as s}from"./chunks/framework.D5hoimZQ.js";const P=JSON.parse('{"title":"🔬 科学日报 | 2026年8月2日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-08-02.md","filePath":"science-log/src/science-daily/2026-08-02.md"}'),g={name:"science-log/src/science-daily/2026-08-02.md"};function e(a,o,i,p,c,d){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年8月2日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年8月2日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年8月2日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年8月2日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：事后重建版简讯（science-log/src/reconstructed/2026-08-02.md，共 10 条：科学 5 + AI 5） 分析日期：2026-08-02 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-06 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-用氟化钾做「appel-氟化」-醇到烷基氟的催化通用路线" tabindex="-1">1. 用氟化钾做「Appel 氟化」：醇到烷基氟的催化通用路线 <a class="header-anchor" href="#_1-用氟化钾做「appel-氟化」-醇到烷基氟的催化通用路线" aria-label="Permalink to &quot;1. 用氟化钾做「Appel 氟化」：醇到烷基氟的催化通用路线&quot;">​</a></h3><p><strong>原文</strong>：Appel 反应（PPh₃/CX₄ 把醇变卤代烃）是实验室最常见的羟基替换手段，但唯独做不了氟化物：氟离子会被磷试剂螯合成二氟膦烷（difluorophosphorane）而彻底失活。</p><p><strong>深度扩展</strong>：</p><p>Mondal A、Struijs J、Doyle C 等 <strong>12 位作者</strong>（<em>Science</em>, 2026-07-30）做的不是「改良条件」，而是<strong>换掉磷试剂的身份</strong>。经典 Appel 的失败是热力学性的：P⁵⁺ 一旦抓到两个氟，就形成异常稳定的二氟膦烷，反应从此停在死点，无法再把氟交给碳。作者的解法是把「氟的搬运工」改成<strong>新戊氧基膦盐</strong>：这类盐在台式条件下稳定、可称量，进入反应后先形成一个<strong>新戊氧基氟膦烷</strong>（只有一个 P–F 键），它与底物醇发生<strong>可逆的烷氧基/氟交换</strong>——因为是可逆的，体系不会像二氟膦烷那样被锁死，而是持续把氟输送给碳。真正让反应跑起来的是<strong>氢键相转移催化</strong>：催化剂一端通过氢键「拖」住 KF，使这个几乎不溶于有机相的便宜氟源进入反应相，另一端协助 <strong>P–F 键解离</strong>。这条「可逆交换 + 相转移」的组合，使氟化从「必须用 DAST/Deoxo-Fluor 这类高危险试剂」变成「用 KF 这种一公斤几十块的盐」。为什么重要：烷基氟在药物化学里是刚性需求——C–F 键能提高代谢稳定性、改变 pKa 与构象，¹⁸F 更是 PET 显像的主力核素；而<strong>可逆的烷氧基交换</strong>意味着手性醇有望在<strong>构型保持</strong>下被氟替换，实现此前只有酶催化才能做到的对映选择性氟化。</p><p><strong>跨主题关联</strong>：合成方法学上的「便宜试剂 + 催化循环」范式，与 <code>topics/materials/index.md</code> 里对催化与膜材料的记录同构；氟化学的制药动机见 <code>topics/biomedicine/index.md</code>。</p><h3 id="_2-血红素合成的负反馈被补全-poldip2-是线粒体蛋白酶-clpxp-的血红素感应接头" tabindex="-1">2. 血红素合成的负反馈被补全：POLDIP2 是线粒体蛋白酶 CLPXP 的血红素感应接头 <a class="header-anchor" href="#_2-血红素合成的负反馈被补全-poldip2-是线粒体蛋白酶-clpxp-的血红素感应接头" aria-label="Permalink to &quot;2. 血红素合成的负反馈被补全：POLDIP2 是线粒体蛋白酶 CLPXP 的血红素感应接头&quot;">​</a></h3><p><strong>原文</strong>：已知血红素会诱导血红素合成限速酶 ALAS 经线粒体酪蛋白水解酶复合体 CLPX–CLPP（CLPXP）降解，但「血红素如何被读成降解信号」一直是缺口。</p><p><strong>深度扩展</strong>：</p><p>Cottle T、Joh L、Posner C 等 <strong>8 位作者</strong>（<em>Science</em>, 2026-07-30）补的正是这条链上丢失的<strong>传感器</strong>环节。原来的因果链断在中间：血红素浓度上升 → ??? → CLPXP 降解 ALAS。CLPXP 是<strong>AAA+ 家族</strong>的线粒体基质蛋白酶，它的底物识别依赖<strong>接头蛋白（adaptor）<strong>把带降解决定簇的底物递进蛋白酶腔——这是细菌与线粒体共有的「标签 + 传送带」逻辑。作者用</strong>体外重建</strong>做了最强的一步证明：只用 POLDIP2、血红素-ALAS、CLPXP 三者，就能<strong>重现负反馈降解</strong>，说明不需要别的因子。细胞层面，POLDIP2 缺失使 ALAS 无法正常周转；在<strong>红系分化</strong>过程中，POLDIP2 水平成为血红素产量的调节旋钮。生化上，POLDIP2 <strong>直接结合血红素结合的 ALAS</strong>（即它读的是「已经装好血红素的 ALAS」这一构象，而非游离血红素），降解起始还需要 <strong>ALAS 的羧基端元件</strong>——这解释了为什么截短的 ALAS 变体抗降解。为什么重要：卟啉病与铁粒幼细胞贫血都涉及这条通路的失衡；更重要的是它给出了一个<strong>通用的调控母题</strong>——代谢物不直接抑制酶活性，而是通过<strong>接头蛋白</strong>改变酶的<strong>半衰期</strong>。这种「用降解替代抑制」的设计让响应不可逆、且能迅速清空已有的酶，适合处理<strong>有毒中间物</strong>。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 中的蛋白稳态/降解通路记录相接；「代谢物→接头→蛋白酶」的控制结构与 <code>topics/ai-system-architecture/index.md</code> 里的资源回收/GC 设计形成同构。</p><h3 id="_3-海王星的内卫星与环是「冰质天体内部」的裸露残骸-jwst-抓到-2-72-μm-富镁层状硅酸盐" tabindex="-1">3. 海王星的内卫星与环是「冰质天体内部」的裸露残骸：JWST 抓到 2.72 μm 富镁层状硅酸盐 <a class="header-anchor" href="#_3-海王星的内卫星与环是「冰质天体内部」的裸露残骸-jwst-抓到-2-72-μm-富镁层状硅酸盐" aria-label="Permalink to &quot;3. 海王星的内卫星与环是「冰质天体内部」的裸露残骸：JWST 抓到 2.72 μm 富镁层状硅酸盐&quot;">​</a></h3><p><strong>原文</strong>：Davis M、Belyakov M、Wong I 等 5 位作者用 JWST 观测了环以及 Larissa、Galatea、Proteus 三颗内卫星。</p><p><strong>深度扩展</strong>：</p><p>这项发表在 <em>Science Advances</em>（2026-07-31）的观测，把一台为系外行星大气设计的望远镜用在了自家后院的「脏活」上。难点在于海王星内卫星极小（Proteus 直径约 420 km，Larissa 约 200 km，Galatea 约 180 km）、反照率极低、且紧贴明亮的行星与环，地面望远镜几乎无法取得<strong>2–4 μm 的干净光谱</strong>；JWST 的 NIRSpec/近红外仪器在这个波段既有灵敏度又有空间分辨力。观测结果的关键不在「发现了什么」，而在**「没发现什么」<strong>：没有水冰的特征吸收，却有很深的 <strong>3 μm OH 带</strong>——OH 带在含水矿物与冰里都会出现，缺少配套的冰特征就把解释推向「水被锁在矿物结构里」。真正的指纹是 <strong>2.72 μm</strong>：这是 <strong>Mg-层状硅酸盐（蛇纹石/滑石类）</strong> 的 OH 伸缩泛频位置，在外太阳系天体上此前</strong>从未<strong>被确认，而它在地球上正是</strong>蛇纹石化**（橄榄石 + 水 → 蛇纹石 + 磁铁矿 + H₂）的产物标记。逻辑闭环由此成立：层状硅酸盐只能在<strong>有液态水、且持续足够久</strong>的环境里生成，而今天这些小天体太小、太冷，不可能有液态水——所以它们<strong>不是原地形成的</strong>，而是<strong>某个更大的母体内部</strong>的碎片。最自然的母体候选，就是 Triton 被捕获过程中被撞碎或潮汐撕裂的原始卫星。为什么重要：它把「Triton 是外来者」这个由<strong>轨道倾角与逆行</strong>支撑的动力学结论，第一次用<strong>矿物学证据</strong>独立支持；同时提示海王星环是<strong>近期（地质学意义上）碰撞事件的残骸带</strong>，而不是原初星云残留。</p><p><strong>跨主题关联</strong>：太阳系天体水—岩反应与 <code>topics/space-energy/index.md</code> 中行星科学的记录同一线索；蛇纹石化产氢的地球化学逻辑见 <code>topics/earth-science/index.md</code>。</p><h3 id="_4-agrp-神经元是-glp-1-受体激动剂减重效应的「必要条件」-雌鼠" tabindex="-1">4. AgRP 神经元是 GLP-1 受体激动剂减重效应的「必要条件」（雌鼠） <a class="header-anchor" href="#_4-agrp-神经元是-glp-1-受体激动剂减重效应的「必要条件」-雌鼠" aria-label="Permalink to &quot;4. AgRP 神经元是 GLP-1 受体激动剂减重效应的「必要条件」（雌鼠）&quot;">​</a></h3><p><strong>原文</strong>：按教科书框架，弓状核 AgRP 神经元是「饥饿神经元」：负能量平衡时被激活，促摄食、降能耗。</p><p><strong>深度扩展</strong>：</p><p>d&#39;Ávila M、Cavalcanti-de-Albuquerque J、Collado-Pérez R 等 <strong>9 位作者</strong>（<em>PNAS</em>, 2026-08-04）挑战的是一个<strong>推论式的教条</strong>，而不是原始事实。原始事实没错：AgRP 神经元在饥饿时放电、被光遗传激活即诱发进食。错的是把「饥饿时激活」直接翻译成「减重药必须抑制它」。作者的实验设计是<strong>必要性检验</strong>：用多种互补的 <strong>AgRP 功能缺失模型</strong>（不同干预方式、不同时间窗）去削弱这条环路的完整性，然后看 GLP-1RA（含司美格鲁肽）还能减多少重。结果是减重效果<strong>显著缩水</strong>，且这种必要性<strong>随性别、饮食、AgRP 干预方式而变</strong>——在<strong>雌鼠</strong>上最清楚。为什么这个方向反直觉却合理：GLP-1RA 的长期疗效不只是「少吃了」，还包含<strong>能量消耗的重塑、脂肪—瘦体重的重新分配、以及中枢对能量储备的重新估值</strong>；AgRP 神经元不只是「饥饿开关」，它是<strong>能量状态的积分器</strong>，输出到 PVH、LHA、PBN 等多个下游，参与调控交感张力与代谢率。若把这条积分器彻底切断，药物就失去了「重新校准设定点」的把手。方法学上的价值同样重要：肥胖药理长期以<strong>雄鼠</strong>为主，而这里最强的效应出现在雌鼠，提示<strong>性腺激素—能量代谢</strong>的交互会改变药物中枢作用位点，临床上也确有人体数据提示女性对 GLP-1RA 的反应曲线不同。可检验的预测：若 AgRP 环路活性是疗效中介，那么给药前的 AgRP 反应性应能<strong>预测</strong>个体减重幅度。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的代谢药理记录相接；「教条推论 vs 必要性检验」的方法论可对照 <code>topics/science-news/index.md</code> 中的同行评议讨论。</p><h3 id="_5-把「脑龄」从标量变成图谱-体素级局部脑龄模型-14-748-名认知正常者" tabindex="-1">5. 把「脑龄」从标量变成图谱：体素级局部脑龄模型（14,748 名认知正常者） <a class="header-anchor" href="#_5-把「脑龄」从标量变成图谱-体素级局部脑龄模型-14-748-名认知正常者" aria-label="Permalink to &quot;5. 把「脑龄」从标量变成图谱：体素级局部脑龄模型（14,748 名认知正常者）&quot;">​</a></h3><p><strong>原文</strong>：「脑龄」通常被压成一个全局数值（GBA），方便但粗暴：大脑老化在皮层各区的速度并不相同。</p><p><strong>深度扩展</strong>：</p><p>Chaudhari N、Vega Huerta O、Bhattacharya S 等 <strong>6 位作者</strong>（<em>PNAS</em>, 2026-08-03）的技术路线值得拆开看。<strong>全局脑龄（GBA）<strong>的做法是：训练一个网络从结构 MRI 预测年龄，然后取「预测年龄 − 实际年龄」的</strong>残差</strong>作为「脑老化加速」的指标。它的问题有两层：一是<strong>信息瓶颈</strong>——把上千个体素压成一个标量，必然丢掉空间分布；二是<strong>混淆</strong>——不同区域的老化梯度被平均掉后，一个「前颞叶提前老化」的人和一个「全脑均匀老化」的人可能得到同一个分数，而两者的临床含义完全不同。作者改成<strong>体素级回归</strong>（local brain age, LBA），在 <strong>14,748 名 CN 参与者</strong>、多中心 <strong>T1 MRI</strong> 上训练。训练规模是关键：体素级预测的样本效率极差，单中心几百例必然过拟合到站点效应，多中心 1.4 万例才让「哪些区域的预测更准」成为可解释的信号而非噪声。结果给出稳定的<strong>空间梯度</strong>：<strong>额叶与颞叶 &gt; 顶叶与枕叶</strong>，这与已知的皮层髓鞘化/铁沉积/代谢率的成年期梯度方向一致，是一个<strong>外部合理性检验</strong>。随后在 <strong>1,102 名 CN 老年人</strong>上，作者看到前颞叶等区域的<strong>渐进性超前老化</strong>并与认知相关——前颞叶正是 <strong>AD 病理（Braak 分期）最早累积</strong>的位置。为什么重要：它把「脑龄」从<strong>体检式的一个数字</strong>变成<strong>一张可定位的脆弱性地图</strong>，从而有望在症状出现前给出<strong>区域特异的预警</strong>；也提供了对「认知储备」假说的可量化检验入口——储备高的个体应当在<strong>同一实际年龄下区域脑龄更年轻</strong>。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code> 的脑老化与影像表型记录同线；深度学习影像模型的可解释性问题可对照 <code>topics/intelligence-self-learning/index.md</code>。</p><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-v-mem-按「模态路由」检索的长期多模态智能体记忆" tabindex="-1">6. V-Mem：按「模态路由」检索的长期多模态智能体记忆 <a class="header-anchor" href="#_6-v-mem-按「模态路由」检索的长期多模态智能体记忆" aria-label="Permalink to &quot;6. V-Mem：按「模态路由」检索的长期多模态智能体记忆&quot;">​</a></h3><p><strong>原文</strong>：现有智能体记忆几乎都建立在文本上，少数支持多模态的系统在视觉相关提问上依旧失败。</p><p><strong>深度扩展</strong>：</p><p>Kang Dingyi、Jiang Dongming、Li Yi、Li Guanpeng 等 <strong>5 位作者</strong>（arXiv 2608.01543）的诊断比方法更有价值。他们指出多模态记忆的失败<strong>不是检索器不够强</strong>，而是<strong>相似度检索这个范式本身</strong>在跨模态时失效——由此拆出两道结构性裂缝。<strong>模态鸿沟</strong>：联合嵌入空间虽然把图文映到一处，但分布仍有系统性偏移，同模态内容彼此更近，于是「以文查图」天然吃亏。<strong>相似–相关鸿沟</strong>：检索假设「最相似 = 最有用」，但<strong>回答问题的证据常常与问题不相似</strong>——问「他当时穿什么颜色的外套」，相关证据是一张照片，照片与这句话的嵌入距离可能远大于另一段同话题的文字。当查询<strong>同时含文本和图像</strong>时，两块证据<strong>各自都不像</strong>完整查询，鸿沟最深。V-Mem 的两个动作因此都非常「非检索」：<strong>①按轮（round）取回</strong>——先判定目标模态，只在<strong>同一轮对话</strong>里取该模态内容，彻底不做跨模态比较；<strong>②用 LLM 造锚点</strong>——纯文本查图时生成<strong>假想图注</strong>当查询向量，需图文联合时把<strong>查询文本 + 从查询图抽出的关键词</strong>拼成更贴近证据的锚。数字很硬：<strong>Mem-Gallery</strong> 上 LLM 判分 <strong>0.82 vs 次优 0.56</strong>，带图问题 <strong>0.87 vs 全部基线 ≤0.47</strong>；<strong>LoCoMo</strong> 0.69 vs 0.58。带图项上近两倍的差距说明：一旦跨模态比较被<strong>路由</strong>替代，性能跃升不是微调级而是范式级。可质疑处：锚点由 LLM 生成，引入了一个<strong>新的幻觉面</strong>——假想图注若描述错，检索会被稳定地引向错误证据。</p><p><strong>跨主题关联</strong>：直接对标 <code>topics/ai-brain/index.md</code> 的记忆/检索设计——本知识库的 <code>scripts/semantic_search.py</code> 与 <code>links/links.md</code> 正是「相似度检索 + 关键词关联」两条路线；V-Mem 的教训是<strong>两张索引不能混用同一把尺</strong>。</p><h3 id="_7-以题生题-qbq-给竞赛数学的强化微调装上自演化课程" tabindex="-1">7. 以题生题（QbQ）：给竞赛数学的强化微调装上自演化课程 <a class="header-anchor" href="#_7-以题生题-qbq-给竞赛数学的强化微调装上自演化课程" aria-label="Permalink to &quot;7. 以题生题（QbQ）：给竞赛数学的强化微调装上自演化课程&quot;">​</a></h3><p><strong>原文</strong>：教模型一项它尚未掌握的技能，卡在三处：数据稀缺、没有可信的推理轨迹（oracle reasoning）、以及明显的能力天花板。</p><p><strong>深度扩展</strong>：</p><p>Bao Longtian、Wang Jianyou、Zhang Yang、Zheng Youze 等 <strong>5 位作者</strong>（arXiv 2608.01522）把三个困难<strong>同时</strong>当成设计约束，这是它比多数合成数据工作干净的地方。<strong>①数据稀缺</strong>：AIME 级别题目总量只有几百道，直接 RL 必然过拟合；QbQ 让教师把原题<strong>改写成变体</strong>（改数值、改结构、改问法），探同一组底层技能，从而把「几百题」变成「可控规模的技能探针」。<strong>②无 oracle 推理</strong>：多数自蒸馏方法依赖教师的思维链，但教师推理<strong>本身可能错</strong>，错误轨迹被蒸馏进去就是灾难；作者<strong>只用题面 + 最终答案</strong>做<strong>可验证奖励（RLVR）</strong>，彻底绕开轨迹质量问题——这也让奖励信号客观、不可作弊。<strong>③能力天花板</strong>：实验显示<strong>静态训练</strong>（真实 + 合成混合，或不做课程调度的 QbQ 数据）都会<strong>在远未达到目标处平台化</strong>；提升来自<strong>自演化课程</strong>——随模型变强，采样题目的难度与技能覆盖同步上移，始终维持在「略高于当前能力」的学习区。这与<strong>最近发展区（ZPD）<strong>的教育学直觉完全对应，也在工程上给出可操作的判据：合成数据的价值 = <strong>难度分布与当前能力的匹配度</strong>，而不是</strong>条目总数</strong>。方法局限：难度调度需要可靠的难度估计器，而在数学题上「难度」本身是模型相关的，估计器一旦偏，课程就会卡在伪平台。</p><p><strong>跨主题关联</strong>：与 <code>topics/intelligence-self-learning/index.md</code> 的自学习/课程设计记录同构；「只用可验证结果做奖励」的原则可对照 <code>topics/ai-system-architecture/index.md</code> 的评估设计。</p><h3 id="_8-minegrad-只上传-lora-梯度也不安全——联邦微调的解析式梯度反演攻击" tabindex="-1">8. MineGrad：只上传 LoRA 梯度也不安全——联邦微调的解析式梯度反演攻击 <a class="header-anchor" href="#_8-minegrad-只上传-lora-梯度也不安全——联邦微调的解析式梯度反演攻击" aria-label="Permalink to &quot;8. MineGrad：只上传 LoRA 梯度也不安全——联邦微调的解析式梯度反演攻击&quot;">​</a></h3><p><strong>原文</strong>：参数高效微调（PEFT）已被搬进联邦学习以省通信与算力：用户先下载预训练模型，本地只训轻量 LoRA 模块、主干冻结，只把 LoRA 参数的梯度上传服务器。</p><p><strong>深度扩展</strong>：</p><p>Sami Hasin Us、Sen Swapneel、Guler Basak <strong>3 位作者</strong>（arXiv 2608.01521）的攻击之所以值得记录，是因为它打破了 PEFT 在联邦学习里的<strong>默认安全叙事</strong>。默认叙事是：主干冻结、只上传<strong>低秩</strong>梯度，泄露面自然小。攻击者的位置被作者设成<strong>恶意服务器</strong>——注意这比「诚实但好奇」强得多：服务器<strong>决定下发什么模型</strong>。于是攻击分两步：<strong>先投毒基座</strong>，在预训练权重里植入特定结构，使 LoRA 梯度对输入数据的依赖变成<strong>可解析的形式</strong>；<strong>再解析反解</strong>——不是靠迭代优化去猜像素（传统梯度反演的笨办法，图像质量差、算力大），而是利用毒化后的权重让「数据 → 梯度」映射接近<strong>线性可逆</strong>，从而<strong>一次性解析重建</strong>私有样本。这个思路的通用教训是：<strong>隐私保证不能只统计「上传了多少参数」，还要看「上传通道是否被对端预先设计」</strong>。联邦学习的安全分析若假设服务器诚实，则 PEFT 确实降低了通信与部分泄露；一旦服务器主动，<strong>基座模型本身就是一个可控的传感器</strong>。防御方向因此要变：不能只在梯度上加噪（会同时毁掉效用），而需要<strong>基座模型完整性验证</strong>（客户端校验下发的权重指纹）或<strong>本地留出探针</strong>检测梯度异常。这也解释了为什么「联邦学习 + PEFT」在真实部署中往往还要叠加<strong>可信执行环境</strong>——把对端从信任模型里彻底移除。</p><p><strong>跨主题关联</strong>：与 <code>topics/cybersecurity/index.md</code> 的威胁建模记录同线；「基础设施被预先操纵 → 上层指标全失真」的结构，与 <code>topics/quality-products/index.md</code> 里的测量系统污染问题同构。</p><h3 id="_9-denialrag-单文档投毒的新花样——把正确答案「点名然后否认」" tabindex="-1">9. DenialRAG：单文档投毒的新花样——把正确答案「点名然后否认」 <a class="header-anchor" href="#_9-denialrag-单文档投毒的新花样——把正确答案「点名然后否认」" aria-label="Permalink to &quot;9. DenialRAG：单文档投毒的新花样——把正确答案「点名然后否认」&quot;">​</a></h3><p><strong>原文</strong>：RAG 语料投毒的威胁模型很干净：攻击者只需往检索库里塞一篇精心构造的文档，就能把 LLM 引向攻击者选定的错误答案。</p><p><strong>深度扩展</strong>：</p><p>Zhurekbay Abay、Liu Tao、Li Fan <strong>3 位作者</strong>（arXiv 2608.02678）的攻击设计里藏着一个关于 LLM 的<strong>行为学观察</strong>，值得单独记录。以往单文档投毒有一条<strong>不成文的自我约束</strong>：毒文档里<strong>不提</strong>正确答案、只把错误答案写得极其详实。原因是早期的模型（与早期的评测）倾向于「谁出现得具体就信谁」，提正确答案反而给了模型纠正的机会。DenialRAG 反过来利用<strong>另一条</strong>偏好：LLM 对<strong>内部自洽、带解释的叙述</strong>有强烈倾向，而对**「被明确反驳过的信息」<strong>会显著降权。于是毒文档的结构变成三段：<strong>点名正确答案 → 否认它（给出看似合理的理由）→ 提供攻击者控制的解释支持错误答案</strong>。这样模型看到的上下文里，正确答案</strong>不是缺席，而是被标记为已被驳倒**——冲突被前移到检索内容内部，模型没有「另一份干净证据」可以对冲。评测规模不小：<strong>3 个开放域 QA 数据集、8 个来自 4 家厂商的 LLM、5 种推理期防御</strong>，并与 4 篇已发表的单文档投毒攻击横向对比。它对本知识库的直接含义是：<strong>检索命中正确文档 ≠ 答案正确</strong>。知识库越大、越多来源相互矛盾（这在长期积累的个人知识库里是常态），「冲突消解」就越依赖生成器在<strong>同一上下文内的判断力</strong>，而这恰恰是投毒者能操纵的层。可推得的防御方向：<strong>来源可信度分层</strong>（谁的文档、写入时间、是否人工审核）比<strong>内容一致性检查</strong>更可靠——因为内容一致性正是攻击者伪造的东西。</p><p><strong>跨主题关联</strong>：与 <code>topics/cybersecurity/index.md</code> 的投毒/供应链攻击记录同线；本库的 <code>topics/ai-brain/index.md</code> 与 <code>links/links.md</code> 属于「自建语料 + 检索增强」形态，天然共享这一威胁面。</p><h3 id="_10-用-lean-4-自动判定「新颖性」-能编译不等于新-也不等于对" tabindex="-1">10. 用 Lean 4 自动判定「新颖性」：能编译不等于新，也不等于对 <a class="header-anchor" href="#_10-用-lean-4-自动判定「新颖性」-能编译不等于新-也不等于对" aria-label="Permalink to &quot;10. 用 Lean 4 自动判定「新颖性」：能编译不等于新，也不等于对&quot;">​</a></h3><p><strong>原文</strong>：AI 做数学目前只保证正确性，不保证新颖性：一个自动生成的定理可以在 Lean 里零错误编译，却是早已被证明过的结果。</p><p><strong>深度扩展</strong>：</p><p>Porto Ayrton（<strong>单人作者</strong>，arXiv 2608.14669）的 <strong>AViD Journal</strong> 是一条<strong>端到端审查流水线</strong>，它的结构本身就是对「AI 科研评审」的命题拆解：<strong>输入 LaTeX → 形式化到 Lean 4 → 三维判决</strong>。三个维度分别对应「新不新」的三个必要条件：<strong>①存在性</strong>——查 <strong>Mathlib</strong>（形式化语料）与 <strong>TheoremSearch / Matlas</strong>（非形式语料检索库），并加<strong>时间过滤</strong>（防止用未来的论文判定过去的结果）与 <strong>LLM 判官</strong>（处理表述差异）；<strong>②非平凡性</strong>——用<strong>自动 tactic</strong> 尝试解决，若 <code>simp</code>/<code>aesop</code> 一类就能收，说明结论过于浅显；<strong>③结构距离</strong>——把证明的<strong>前提集合</strong>取出，用 <strong>Jaccard 距离</strong>与已有证明比对，衡量「是不是换了个壳的同一证明」。这个第三维尤其重要：它把「新颖」从<strong>结论层面</strong>推进到<strong>证明层面</strong>，这正是形式化的独特优势——自然语言里「证明不同」几乎是不可计算的，而在 Lean 里 premise set 是可枚举的集合。评估用<strong>因重复声明而被 arXiv 撤稿</strong>的论文，这是个聪明但脆弱的基准。作者诚实地报告了<strong>三个与实现无关的障碍</strong>：<strong>Lean 编译成功不等于语义保真</strong>（把定理形式化时可能悄悄弱化或加强了命题，编译通过只说明形式化版本自洽）；<strong>召回上限由定理索引的覆盖度决定</strong>，不是相似度算法的锅（Mathlib 之外的结果检索不到）；<strong>arXiv 撤稿会删除源码</strong>，使此类基准<strong>不可复现</strong>。这三点合起来说明：自动化新颖性审查的瓶颈<strong>不在算法，而在知识库的完整性与形式化的保真度</strong>——一个「索引不全的检索器 + 一个可能失真的翻译器」，无论后面接多强的判官都不够。</p><p><strong>跨主题关联</strong>：与 <code>topics/intelligence-self-learning/index.md</code> 的符号/形式化推理记录相接；「基准不可复现 → 结论无法累积」的教训与 <code>topics/science-news/index.md</code> 的可重复性讨论同构。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-用「半衰期」而不是「活性」来调控——poldip2-→-clpxp-→-alas-的完整因果链" tabindex="-1">机制一：用「半衰期」而不是「活性」来调控——POLDIP2 → CLPXP → ALAS 的完整因果链 <a class="header-anchor" href="#机制一-用「半衰期」而不是「活性」来调控——poldip2-→-clpxp-→-alas-的完整因果链" aria-label="Permalink to &quot;机制一：用「半衰期」而不是「活性」来调控——POLDIP2 → CLPXP → ALAS 的完整因果链&quot;">​</a></h3><p>这条链值得逐段拆开，因为它展示了一种与「变构抑制」完全不同的调控语法。</p><p><strong>第一段：底物必须先被「标记」</strong>。ALAS 是血红素合成的限速酶，它的蛋白量而非催化活性才是通量的主控变量。血红素与 ALAS 的结合会改变 ALAS 的构象（具体是使其 C 端一段原本柔性或埋藏的区域暴露），这段<strong>羧基端元件</strong>是后续步骤所必需的降解决定簇（degron）——实验中截掉它，ALAS 就不再被降解，这是「起始需要 C 端元件」的直接证据。</p><p><strong>第二段：接头蛋白是「读卡器」</strong>。CLPXP 由 <strong>CLPX</strong>（六聚体，AAA+ unfoldase，负责识别、抓取、去折叠并送入腔内）与 <strong>CLPP</strong>（十四聚体的丝氨酸蛋白酶腔）组成。CLPX 自身对大多数底物识别能力弱，需要<strong>接头蛋白</strong>桥接：接头一端结合 CLPX 的表面位点，另一端结合底物的降解决定簇，从而把「识别」与「降解」解耦。<strong>POLDIP2</strong> 就是这样一个接头，而且它的特殊之处在于<strong>它自己感应血红素</strong>——它不是被某种信号磷酸化后才上岗，而是直接结合<strong>已经装载血红素的 ALAS</strong>。这一步是整条链的传感器环节：血红素浓度上升 → 血红素-ALAS 构象暴露 C 端 → POLDIP2 识别并结合 → 递送给 CLPX。</p><p><strong>第三段：为什么必须用降解而不是抑制</strong>。抑制是可逆的、瞬时的；降解是不可逆的、且<strong>清空库存</strong>。对血红素这种「中间产物有毒」的通路，需要的是<strong>快速降低通量并清除已经造好的酶</strong>——因为即使在酶被抑制后，已存在的 ALAS 仍会继续产出有毒卟啉前体。这也解释了为什么负反馈选择蛋白水解：<strong>只有降解能同时关掉「未来产能」和「当前库存」</strong>。</p><p><strong>可证伪预测</strong>：若上述链条正确，则 (a) 在 POLDIP2 缺失细胞中人为融合一个泛素无关的降解决定簇到 ALAS 上，应能<strong>部分恢复</strong>血红素耐受；(b) 在红系分化中过表达 POLDIP2 应使血红素产量<strong>下降</strong>而非上升；(c) 若把 ALAS 的 C 端元件删去，则 POLDIP2 与 ALAS 的结合应保留但降解不发生。这三条都能直接证伪「POLDIP2 是唯一接头」或「C 端是唯一起始点」的说法。</p><h3 id="机制二-设定点是被「积分」的-不是被「开关」的——agrp-环路与-glp-1ra-的必要性" tabindex="-1">机制二：设定点是被「积分」的，不是被「开关」的——AgRP 环路与 GLP-1RA 的必要性 <a class="header-anchor" href="#机制二-设定点是被「积分」的-不是被「开关」的——agrp-环路与-glp-1ra-的必要性" aria-label="Permalink to &quot;机制二：设定点是被「积分」的，不是被「开关」的——AgRP 环路与 GLP-1RA 的必要性&quot;">​</a></h3><p>反直觉结果的背后是一个关于<strong>控制系统拓扑</strong>的问题。</p><p><strong>经典模型是开关式的</strong>：AgRP 神经元 = 饥饿信号，激活 → 吃；GLP-1RA = 饱信号，抑制 AgRP → 不吃。这个模型能解释<strong>单餐摄食量</strong>，但解释不了<strong>持续数月的体重下降</strong>——因为按开关模型，抑制信号一旦撤除（或下游适应），体重就该反弹。</p><p><strong>另一种模型是积分器式的</strong>：AgRP 神经元并不传递「饿」这个瞬时量，而是持续整合<strong>脂肪储备、瘦体重、 leptin 与 ghrelin 水平、能量可用性</strong>，把结果作为一个<strong>设定点偏差</strong>广播给下游（PVH 的 TRH 神经元、LHA 的 orexin/MCH 神经元、PBN 的饱中枢）。GLP-1RA 的作用不是把它「关掉」，而是<strong>改变它读到的输入</strong>（通过 GLP-1R 在弓状核与孤束核的分布、以及迷走—NTS 通路的传入），从而<strong>重设设定点</strong>。若把 AgRP 环路整体破坏，药物仍能通过 NTS/PBN 产生部分效应（这解释了为何减重只是「缩水」而非「消失」），但<strong>失去了主要的积分器</strong>，长期重设就无从落地。</p><p>这也与拟议的性别差异相容：雌性在动情周期中的能量需求波动更大，AgRP 环路的<strong>增益</strong>（gain）被性激素调制；若环路增益是关键变量，那么在同一药物剂量下，雌鼠的效应应当<strong>更依赖</strong>这条环路的完整性——这与观测一致。</p><p><strong>关键的可检验推论</strong>：若 AgRP 是积分器，那么（a）给药后早期 AgRP 神经元的<strong>瞬时反应</strong>（不是平均放电率）应能预测数月后的减重幅度；（b）选择性只破坏 AgRP→PVH 投射（保留 →LHA/PBN）应产生<strong>部分</strong>而非全面削弱，且不同投射的贡献可与体重成分（脂肪 vs 瘦体重）对应。这比「AgRP 是饥饿开关」的旧模型给出了更细的分解。</p><h3 id="机制三-绕过热力学死点的两种方式——可逆交换的化学-与矿物晶格的物理" tabindex="-1">机制三：绕过热力学死点的两种方式——可逆交换的化学，与矿物晶格的物理 <a class="header-anchor" href="#机制三-绕过热力学死点的两种方式——可逆交换的化学-与矿物晶格的物理" aria-label="Permalink to &quot;机制三：绕过热力学死点的两种方式——可逆交换的化学，与矿物晶格的物理&quot;">​</a></h3><p>本期两条看似无关的条目（KF 氟化、海王星 2.72 μm）其实是同一个<strong>方法论母题</strong>：当一条路径被某个稳定的中间态堵死，解法通常是<strong>换掉中间态的稳定性来源</strong>。</p><p><strong>化学侧</strong>：Appel 氟化死在<strong>二氟膦烷</strong>上，因为它热力学稳定、形成后不可逆。新路线的关键是把中间体改成<strong>单氟的新戊氧基氟膦烷</strong>，并让它的<strong>烷氧基/氟交换可逆</strong>——可逆意味着体系不会单向下沉到一个死态，而是持续维持一个<strong>低浓度但高活性的氟供体池</strong>。相转移催化解决的是另一端的瓶颈：<strong>KF 在有机相中的溶解度</strong>。氟离子是小、硬、强溶剂化的阴离子，其晶格能高，几乎不溶于非极性溶剂；氢键供体催化剂通过<strong>部分脱溶剂化</strong>把 F⁻ 「拎」进有机相，同时削弱 P–F 键，使氟转移的过渡态能量下降。这是典型的<strong>两条瓶颈串联</strong>问题：中间体稳定性 + 相分配系数，缺一不可。</p><p><strong>物理侧</strong>：2.72 μm 这条吸收带的诊断力来自<strong>晶格而非成分</strong>。Mg-层状硅酸盐（蛇纹石、滑石）的结构是 <strong>T–O（四面体–八面体）层</strong>，Mg²⁺ 占据八面体位，OH 基团指向层间；其 OH 伸缩泛频位置受<strong>八面体配位环境与氢键几何</strong>的精确约束，因此 2.72 μm 不是「有 OH」的证据（3 μm 才能给这个），而是「OH 处于特定的 Mg 八面体 + 层状堆垛环境」的证据。同理，<strong>缺少结晶水冰的特征</strong>排除了「冰 + 尘埃混合物」这一最平凡的解释。两条约束（有 OH 但非冰；OH 处于层状 Mg 环境）合起来，等于在光谱层面<strong>唯一地</strong>指向水蚀变产物——这就是为什么一条 2.72 μm 带能承担「母体曾有液态水」这么大的推论。</p><p><strong>共同逻辑</strong>：诊断力不来自「检测到某个东西」，而来自<strong>对同一个量的多路约束</strong>。化学里是「可逆性 + 相分配」，天文里是「OH 带 + 无水冰特征 + 泛频精确位置」，生物学里是「结合 + C 端暴露 + 降解发生」——<strong>单点信号永远可被平凡解释，约束的交集才有信息量</strong>。</p><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-调控的精度来自「对同一物理量的不同敏感度」-而非来自新的分子" tabindex="-1">原理一：调控的精度来自「对同一物理量的不同敏感度」，而非来自新的分子 <a class="header-anchor" href="#原理一-调控的精度来自「对同一物理量的不同敏感度」-而非来自新的分子" aria-label="Permalink to &quot;原理一：调控的精度来自「对同一物理量的不同敏感度」，而非来自新的分子&quot;">​</a></h3><p>本期三条生物学/材料学结果共享一条底层规律：<strong>系统不需要为每一个控制目标发明一个新元件，只需要让已有元件对同一个量的敏感度不同</strong>。</p><p>POLDIP2 感应的是<strong>血红素-ALAS 复合物的构象</strong>，不是血红素浓度本身；AgRP 积分的是<strong>能量储备的多路加权和</strong>，不是血糖或 leptin 单一值；层状硅酸盐的 2.72 μm 带读的是<strong>八面体配位几何</strong>，不是含水量。三者的共同点是：<strong>把「浓度/总量」这一低信息量标量，转换成「构象/加权和/配位环境」这一高信息量结构</strong>——因为标量可以被任何原因产生（噪声、旁路、污染），而结构只能由特定历史产生。</p><p>这条原理有可证伪的形式：若调控确实依赖「结构而非浓度」，则人为把浓度提到与生理相同但<strong>破坏结构</strong>（例如用不能诱导构象变化的血红素类似物、或用不改变能量储备分布的方式灌胃）应当<strong>不触发</strong>相应响应。这正是可以设计的对照实验，也是判断一个「传感器」是真感应结构还是仅仅感应浓度的唯一判据。</p><p><strong>演化上的必然性</strong>：任何依赖「浓度阈值」的控制回路都会被<strong>噪声与旁路</strong>欺骗（受体上调、缓冲体系、非特异结合），而依赖「结构匹配」的回路只能被<strong>精确模拟该结构</strong>的信号欺骗——后者的欺骗成本高得多。这就是为什么生物系统在关键节点上几乎都使用<strong>构象识别</strong>（接头蛋白、抗体、转录因子的变构）而不是浓度阈值。同理，AI 系统里靠「相似度阈值」做检索（V-Mem 批评的那种）会被<strong>同模态、话术相近</strong>的内容欺骗，而靠「路由 + 结构化锚点」的方案欺骗成本更高。</p><h3 id="原理二-信息不会因为「维度降低」而消失-只会因为「通道被设计」而暴露" tabindex="-1">原理二：信息不会因为「维度降低」而消失，只会因为「通道被设计」而暴露 <a class="header-anchor" href="#原理二-信息不会因为「维度降低」而消失-只会因为「通道被设计」而暴露" aria-label="Permalink to &quot;原理二：信息不会因为「维度降低」而消失，只会因为「通道被设计」而暴露&quot;">​</a></h3><p>MineGrad 与 DenialRAG 指向同一条信息论事实的两面。</p><p><strong>MineGrad 的一面</strong>：LoRA 只上传秩 r 很低的梯度矩阵，参数数目远小于数据维度，直觉上「信息不够重建数据」。但梯度是<strong>数据对参数的导数</strong>，在<strong>权重被预先设计</strong>的情形下，这个映射可以被做成<strong>近似线性可逆</strong>——于是「低秩」不再是保护，因为可逆性不取决于秩，而取决于<strong>映射的结构</strong>。用信息论的话说：泄露量下界由<strong>输入在该映射下的像</strong>决定，而不是由<strong>映射的输出维度</strong>决定；一个精心构造的低维投影足以保留全部信息（这正是压缩感知的前提）。<strong>必然推论</strong>：任何「因为上传的东西少所以安全」的论证都是无效的，除非能证明该映射对输入是<strong>信息压缩的</strong>（例如严格的信息瓶颈，或注入与输入无关的噪声使像集不可分）。</p><p><strong>DenialRAG 的一面</strong>：RAG 的隐含假设是「检索到的上下文包含正确信息 → 生成器会输出正确答案」。这等价于假设<strong>生成器对上下文中的信息做无偏整合</strong>。但生成器是一个<strong>有偏的推断器</strong>：它对「有解释的叙述」赋更高权重，对「被反驳的陈述」赋更低权重。于是攻击者不需要<strong>删除</strong>正确信息，只需要<strong>改变它的呈现地位</strong>——信息的<strong>存在</strong>与信息的<strong>可用</strong>被解耦了。这是一条普遍规律：<strong>任何「把判断外包给下游模型」的架构，其可靠性上限由下游模型的先验决定，而不是由上游的证据质量决定</strong>。</p><p><strong>可证伪预测</strong>：若上述成立，则（a）在 DenialRAG 的毒文档中<strong>只否认不解释</strong>，攻击成功率应显著下降（因为缺少「连贯叙述」这一权重来源）；（b）若在生成前强制要求模型<strong>先列举上下文中所有互相矛盾的陈述</strong>再作答，攻击成功率应下降（把「地位」这一隐变量显式化）；（c）MineGrad 的防御若采用「客户端验证下发权重哈希」，攻击成功率应归零——因为攻击依赖对基座的预先操纵，一旦操纵被检出，可逆性假设即失效。这三条都是可以在实验中直接检验的。</p><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期十条共享一条<strong>统一逻辑：把「判断」从「量」转移到「结构」，并因此把攻击面从「数据」转移到「通道」</strong>。</p><p>科学侧的三条（POLDIP2、AgRP、2.72 μm）都在做同一件事：<strong>不信任标量，信任结构</strong>。血红素浓度是标量，血红素-ALAS 的构象是结构；体重是标量，能量储备的加权积分是结构；3 μm 有 OH 是标量信息（冰也能给），2.72 μm 的泛频位置是结构信息（只有层状 Mg 硅酸盐能给）。三者都因为换用了结构判据，才获得了「单点即可定性」的诊断力。化学侧的 KF 氟化则是<strong>结构性</strong>地绕过热力学死点：不是加大推力（更强亲核试剂、更极端条件），而是把中间体从「不可逆的稳定态」换成「可逆的流动态」——这同样是「改结构而非改量」。</p><p>AI 侧的三条（V-Mem、MineGrad、DenialRAG）则是这条逻辑的<strong>镜像失败案例</strong>：它们展示了「只信量」会怎样崩塌。V-Mem 指出相似度是标量，而「相关性」是结构，用标量代替结构会在跨模态时系统性失效；MineGrad 指出「上传参数量」是标量，「映射的可逆性」是结构，用标量做隐私论证必错；DenialRAG 指出「正确信息是否在上下文中」是标量（0/1），「它在上下文中被赋予什么地位」是结构，攻击者只需改结构不改标量。<strong>三者都是同一个错误的三种表现：把可测量的标量当成可依赖的判据。</strong></p><p>与库内已有主题的深层同构有三处。其一，<code>topics/ai-brain/index.md</code> 的核心设计问题正是这条：本知识库用 <code>links/links.md</code>（关键词共现，标量）与 <code>topics/</code> 的语义结构（结构）双轨并行——本期的教训是<strong>不要把两轨混成一把尺</strong>，关键词命中率高不代表关联有意义。其二，<code>topics/quality-products/index.md</code> 里的测量系统污染与 MineGrad 完全同构：当<strong>测量工具本身被对端控制</strong>，所有下游指标都失去意义，防御只能落在「工具的可信性验证」上。其三，<code>topics/science-news/index.md</code> 的可重复性讨论与 AViD Journal 的三个障碍同构：<strong>「能复现」不是算法属性，而是基础设施属性</strong>（源码是否保留、索引是否完整），这一点在 AI 科研评审与实验科学里是同一条约束。</p><p>一句话收束：<strong>这一期真正的主角不是任何一项发现，而是「判据的层次」——同一个现象，用标量看是噪声，用结构看是信号；同一个系统，用参数看是安全的，用通道看是裸奔的。</strong></p><hr><p>关键词：Appel 反应, Appel reaction, 氟化, fluorination, 氟化钾, potassium fluoride, 新戊氧基膦盐, neopentoxyphosphonium, 二氟膦烷, difluorophosphorane, 氢键相转移催化, hydrogen-bonding phase-transfer catalysis, 对映选择性氟化, 10.1126/science.aec6298, 血红素, heme, ALAS, 5-aminolevulinate synthase, CLPXP, CLPX, CLPP, POLDIP2, 接头蛋白, adaptor, 降解决定簇, degron, 红系分化, erythropoiesis, 10.1126/science.ads5397, 海王星, Neptune, Triton, JWST, 层状硅酸盐, phyllosilicate, 蛇纹石化, serpentinization, Larissa, Galatea, Proteus, 2.72 μm, 水蚀变, aqueous alteration, 10.1126/sciadv.aeb1437, AgRP 神经元, AgRP neurons, GLP-1 受体激动剂, GLP-1 receptor agonist, semaglutide, 司美格鲁肽, 弓状核, arcuate nucleus, 能量设定点, energy set point, 10.1073/pnas.2614476123, 脑龄, brain age, 局部脑龄, local brain age, 体素级, voxel-wise, T1 MRI, 额颞叶, frontotemporal, 阿尔茨海默病, Alzheimer&#39;s disease, 10.1073/pnas.2532233123, 多模态记忆, multimodal memory, 模态鸿沟, modality gap, 检索路由, modality routing, Mem-Gallery, LoCoMo, arXiv 2608.01543, 课程强化学习, curriculum RL, QbQ, 合成数据, synthetic data, RLVR, AIME, Qwen2.5-Math, arXiv 2608.01522, LoRA, 梯度反演, gradient inversion, 联邦学习, federated learning, PEFT, 隐私泄露, privacy leakage, arXiv 2608.01521, RAG 投毒, corpus poisoning, DenialRAG, 参数化否认, parametric denial, arXiv 2608.02678, Lean 4, Mathlib, 新颖性验证, novelty verification, AViD Journal, Jaccard 距离, 形式化, formalization, arXiv 2608.14669</p><p>关联：topics/ai-brain/index.md, topics/biomedicine/index.md, topics/neuroscience/index.md, topics/space-energy/index.md, topics/earth-science/index.md, topics/materials/index.md, topics/cybersecurity/index.md, topics/intelligence-self-learning/index.md, topics/ai-system-architecture/index.md, topics/quality-products/index.md, topics/science-news/index.md, science-log/src/reconstructed/2026-08-02.md, science-log/src/appendix/methodology.md</p>',94)])])}const h=n(g,[["render",e]]);export{P as __pageData,h as default};
